import React, { useEffect, useRef, useMemo } from "react";
import { StyleSheet, View, Text, Platform } from "react-native";
import { WebView } from "react-native-webview";

interface NativeMushafWebViewProps {
  verses: any[];
  wordTimingMap?: { [key: string]: any[] };
  letterTimingMap?: { [key: string]: any[] };
  currentVerseKey: string | null;
  currentTimeMs: number;
  isPlaying: boolean;
  surahNumber: number;
  highlightMode?: 'letter' | 'word' | 'ayah' | 'off';
  onSeekAyah?: (ayah: number) => void;
  onWordSingleClick?: (surah: number, ayah: number, wordIdx: number, wordText: string) => void;
  onWordDoubleClick?: (surah: number, ayah: number, wordIdx: number, wordText: string) => void;
  onWordClick?: (surah: number, ayah: number, wordIdx: number, wordText: string, start?: number, end?: number) => void;
}

const AMIRI_BASE64 = "";

export const NativeMushafWebView: React.FC<NativeMushafWebViewProps> = ({
  verses,
  wordTimingMap,
  letterTimingMap,
  currentVerseKey,
  currentTimeMs,
  isPlaying,
  surahNumber,
  highlightMode = 'word',
  onSeekAyah,
  onWordSingleClick,
  onWordDoubleClick,
  onWordClick,
}) => {
  const webViewRef = useRef<WebView>(null);

  // Normalize timing maps for active Surah so keys are accessible in both "surah:ayah" and "ayah" formats
  const surahTiming = useMemo(() => {
    if (!letterTimingMap) return {};
    const normalized: { [key: string]: any[] } = {};
    for (const k in letterTimingMap) {
      normalized[k] = letterTimingMap[k];
      if (k.includes(':')) {
        const parts = k.split(':');
        if (parts[0] === String(surahNumber)) {
          normalized[parts[1]] = letterTimingMap[k];
        }
      } else {
        normalized[`${surahNumber}:${k}`] = letterTimingMap[k];
      }
    }
    return normalized;
  }, [letterTimingMap, surahNumber]);

  const surahWordTiming = useMemo(() => {
    if (!wordTimingMap) return {};
    const normalized: { [key: string]: any[] } = {};
    for (const k in wordTimingMap) {
      normalized[k] = wordTimingMap[k];
      if (k.includes(':')) {
        const parts = k.split(':');
        if (parts[0] === String(surahNumber)) {
          normalized[parts[1]] = wordTimingMap[k];
        }
      } else {
        normalized[`${surahNumber}:${k}`] = wordTimingMap[k];
      }
    }
    return normalized;
  }, [wordTimingMap, surahNumber]);

  // Serialize lightweight per-surah data into crash-proof, 120 FPS Madani Mushaf HTML DOM
  const htmlContent = useMemo(() => {
    const versesData = verses || [];
    const timingJson = JSON.stringify(surahTiming);
    const wordTimingJson = JSON.stringify(surahWordTiming);
    const hasBismillah = surahNumber !== 9 && (surahNumber !== 1 || (versesData[0] && versesData[0].text && !versesData[0].text.startsWith("بِسْمِ")));

    const digits = ["٠", "١", "٢", "٣", "٤", "٥", "٦", "٧", "٨", "٩"];
    const toAr = (num: number) => num.toString().split("").map(d => digits[parseInt(d, 10)] || d).join("");

    // Build Ayah-by-Ayah continuous Madani Mushaf flow
    const versesHtml = versesData.map(v => {
      const aNum = v.ayah;
      const words = v.words && v.words.length > 0 ? v.words : (v.text || "").trim().split(/\s+/).map((w: any) => ({ arabic: typeof w === "string" ? w : (w.arabic || "") }));
      const wordsMarkup = words.map((w: any, wIdx: number) => {
        const text = typeof w === "string" ? w : (w.arabic || "");
        const chars = text.split("");
        const charsMarkup = chars.map((ch: string, cIdx: number) =>
          `<span class="char" id="c-${aNum}-${wIdx}-${cIdx}" data-ayah="${aNum}" data-word-idx="${wIdx}" data-char-idx="${cIdx}">${ch}</span>`
        ).join("");
        return `<span class="word" id="w-${aNum}-${wIdx}" data-ayah="${aNum}" data-word-idx="${wIdx}" data-word-text="${encodeURIComponent(text)}">${charsMarkup}</span>`;
      }).join(" ");
      return `<span class="ayah-block" id="ayah-${aNum}" data-ayah="${aNum}">${wordsMarkup} <span class="ayah-medallion" data-ayah="${aNum}"> ۝${toAr(aNum)} </span></span>`;
    }).join("\n");

    return `<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
  <style>
    @font-face {
      font-family: 'Amiri Quran';
      src: url('data:font/truetype;charset=utf-8;base64,${AMIRI_BASE64}') format('truetype');
      font-weight: normal;
      font-style: normal;
    }
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      -webkit-tap-highlight-color: transparent;
      user-select: none;
      -webkit-user-select: none;
    }
    html, body {
      background-color: #030712;
      color: #cbd5e1;
      width: 100%;
      min-height: 100%;
      overflow-x: hidden;
      overflow-y: auto;
      font-family: 'Amiri Quran', 'Amiri', serif;
      -webkit-font-smoothing: antialiased;
      direction: rtl;
    }
    .bismillah-container {
      text-align: center;
      padding: 16px 0 10px 0;
      color: #00ffaa;
      font-size: 26px;
      text-shadow: 0 0 12px rgba(0, 255, 170, 0.4);
    }
    .bismillah-border {
      width: 160px;
      height: 1px;
      background: linear-gradient(90deg, transparent, #00ffaa, transparent);
      margin: 6px auto 14px auto;
    }
    .mushaf-container {
      padding: 12px 26px 140px 26px;
      line-height: 2.6;
      text-align: justify;
      text-align-last: center;
      font-size: 25px;
    }
    .ayah-block {
      display: inline;
      padding: 2px 0;
      border-radius: 8px;
      transition: background 0.2s ease;
    }
    .ayah-block.active-ayah {
      background: rgba(251, 191, 36, 0.08);
      box-shadow: 0 0 16px rgba(251, 191, 36, 0.1);
    }
    .word {
      display: inline-block;
      padding: 0 4px;
      margin: 0 1px;
      border-radius: 6px;
      cursor: pointer;
      color: #cbd5e1;
      will-change: color, text-shadow, background;
      transition: color 0.1s ease, text-shadow 0.1s ease, background 0.1s ease;
    }
    .word.word-active {
      background: rgba(0, 255, 170, 0.15);
    }
    .word.reciting {
      color: #00ffaa !important;
      text-shadow: 0 0 16px rgba(0, 255, 170, 0.95), 0 0 30px rgba(0, 255, 170, 0.4);
      background: rgba(0, 255, 170, 0.25);
    }
    .char {
      display: inline;
      transition: color 0.05s ease, text-shadow 0.05s ease;
    }
    .char.active-char {
      color: #00ffaa !important;
      text-shadow: 0 0 14px rgba(0, 255, 170, 0.95), 0 0 28px rgba(0, 255, 170, 0.6);
      font-weight: bold;
    }
    .ayah-medallion {
      display: inline-block;
      color: #fbbf24;
      font-size: 23px;
      margin: 0 5px;
      cursor: pointer;
      text-shadow: 0 0 8px rgba(251, 191, 36, 0.5);
      vertical-align: middle;
      transition: transform 0.15s ease;
    }
    .ayah-medallion:active {
      transform: scale(1.2);
    }
  </style>
</head>
<body>
  ${hasBismillah ? `
    <div class="bismillah-container">
      بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ
      <div class="bismillah-border"></div>
    </div>
  ` : ''}
  <div class="mushaf-container" id="mushafFlow">
    ${versesHtml}
  </div>

  <script>
    const surahNumber = ${surahNumber};
    const letterTimingMap = ${timingJson};
    const wordTimingMap = ${wordTimingJson};

    // Pre-cache DOM elements for O(1) instantaneous lookup (Zero getElementById per frame)
    let activeHighlightMode = "${highlightMode || 'word'}";
    const wordCache = {};
    const charCache = {};
    const ayahCache = {};
    let currentActiveCharEl = null;

    document.querySelectorAll(".char").forEach(function(el) {
      const a = el.getAttribute("data-ayah");
      const w = el.getAttribute("data-word-idx");
      const c = el.getAttribute("data-char-idx");
      if (!charCache[a]) charCache[a] = {};
      if (!charCache[a][w]) charCache[a][w] = {};
      charCache[a][w][c] = el;
    });

    document.querySelectorAll(".word").forEach(function(el) {
      const a = el.getAttribute("data-ayah");
      const w = el.getAttribute("data-word-idx");
      if (!wordCache[a]) wordCache[a] = {};
      wordCache[a][w] = el;
    });

    document.querySelectorAll(".ayah-block").forEach(function(el) {
      const a = el.getAttribute("data-ayah");
      ayahCache[a] = el;
    });

    // High-Precision Hardware Refresh Rate Sync State (60 - 120 FPS)
    let anchorAudioTimeMs = 0;
    let anchorPerfTime = 0;
    let isPlaying = false;
    let currentVerseKey = "";

    let currentRecitingWordEl = null;
    let currentActiveAyahEl = null;
    let lastActiveAyahNum = -1;
    let lastActiveWordIdx = -1;
    let lastScrolledAyah = -1;

    // Direct playback sync entrypoint
    window.updatePlayback = function(timeMs, vKey, playing, mode) {
      currentVerseKey = vKey || "";
      isPlaying = !!playing;
      anchorAudioTimeMs = timeMs || 0;
      anchorPerfTime = performance.now();
      if (mode) activeHighlightMode = mode;

      if (!isPlaying || !currentVerseKey || activeHighlightMode === 'off') {
        if (currentRecitingWordEl) {
          currentRecitingWordEl.classList.remove("reciting", "word-active");
          currentRecitingWordEl = null;
        }
        if (currentActiveCharEl) {
          currentActiveCharEl.classList.remove("active-char");
          currentActiveCharEl = null;
        }
        lastActiveWordIdx = -1;
      }
    };

    function handleIncomingPlaybackMsg(e) {
      try {
        const msg = typeof e.data === "string" ? JSON.parse(e.data) : e.data;
        if (msg.type === "UPDATE_PLAYBACK") {
          window.updatePlayback(msg.currentTimeMs, msg.currentVerseKey, msg.isPlaying, msg.highlightMode);
        }
      } catch (err) {
        console.warn("WebView incoming playback message error:", err);
      }
    }
    window.addEventListener("message", handleIncomingPlaybackMsg);
    document.addEventListener("message", handleIncomingPlaybackMsg);

    if (isPlaying && currentVerseKey) {
      window.updatePlayback(${currentTimeMs || 0}, currentVerseKey, true);
    }

    function syncWordHighlight(aNum, timeMs) {
      const vKey = currentVerseKey || (surahNumber + ":" + aNum);
      const aKey = String(aNum);
      const timingList = wordTimingMap[vKey] || wordTimingMap[aKey] || letterTimingMap[vKey] || letterTimingMap[aKey] || [];
      if (!timingList || timingList.length === 0) return;

      let activeIdx = -1;
      for (let i = 0; i < timingList.length; i++) {
        const entry = timingList[i];
        let st = 0, en = 0, wIdx = -1;
        if (Array.isArray(entry)) {
          wIdx = (typeof entry[0] === "number" && entry[0] >= 1) ? entry[0] - 1 : i;
          st = entry[1] || 0;
          en = entry[2] || 0;
        } else if (entry && typeof entry === "object") {
          wIdx = entry.wordIdx !== undefined ? entry.wordIdx :
                 (entry.w !== undefined ? entry.w :
                 (entry.word !== undefined && typeof entry.word === "number" ? entry.word - 1 : i));
          st = entry.start !== undefined ? entry.start : (entry.s !== undefined ? entry.s : 0);
          en = entry.end !== undefined ? entry.end : (entry.e !== undefined ? entry.e : 0);
        }
        if (st > 0 && st < 100 && en > 0 && en < 300) { st *= 1000; en *= 1000; }
        let effectiveEnd = en;
        const nextEntry = timingList[i + 1];
        if (nextEntry) {
          let nextSt = en;
          if (Array.isArray(nextEntry)) nextSt = nextEntry[1] || en;
          else if (nextEntry && typeof nextEntry === "object") {
            nextSt = nextEntry.start !== undefined ? nextEntry.start : (nextEntry.s !== undefined ? nextEntry.s : en);
            if (nextSt > 0 && nextSt < 100) nextSt *= 1000;
          }
          if (nextSt >= en && (nextSt - en) < 800) effectiveEnd = nextSt;
        }
        if (timeMs >= st && timeMs < effectiveEnd) {
          activeIdx = wIdx;
          break;
        }
      }

      if (activeIdx < 0 && timingList.length > 0) {
        const lastEntry = timingList[timingList.length - 1];
        let lastSt = 0, lastWIdx = -1;
        if (Array.isArray(lastEntry)) {
          lastWIdx = (typeof lastEntry[0] === "number" && lastEntry[0] >= 1) ? lastEntry[0] - 1 : timingList.length - 1;
          lastSt = lastEntry[1] || 0;
        } else if (lastEntry && typeof lastEntry === "object") {
          lastWIdx = lastEntry.wordIdx !== undefined ? lastEntry.wordIdx : (lastEntry.w !== undefined ? lastEntry.w : timingList.length - 1);
          lastSt = lastEntry.start !== undefined ? lastEntry.start : (lastEntry.s !== undefined ? lastEntry.s : 0);
        }
        if (lastSt > 0 && lastSt < 100) lastSt *= 1000;
        if (timeMs >= lastSt) activeIdx = lastWIdx;
      }

      if (activeIdx !== lastActiveWordIdx) {
        if (activeIdx >= 0) {
          const wEl = wordCache[aNum] ? wordCache[aNum][activeIdx] : null;
          if (wEl && wEl !== currentRecitingWordEl) {
            if (currentRecitingWordEl) currentRecitingWordEl.classList.remove("reciting", "word-active");
            wEl.classList.add("reciting");
            currentRecitingWordEl = wEl;
          }
        } else if (currentRecitingWordEl) {
          currentRecitingWordEl.classList.remove("reciting", "word-active");
          currentRecitingWordEl = null;
        }
        lastActiveWordIdx = activeIdx;
      }
    }

    // Hardware-locked 120 FPS requestAnimationFrame render loop with monotonic time extrapolation
    function renderFrame() {
      if (isPlaying && currentVerseKey) {
        const elapsed = performance.now() - anchorPerfTime;
        const timeMs = anchorAudioTimeMs + elapsed;

        const parts = currentVerseKey.split(":");
        const aNum = parseInt(parts[1], 10);

        // 1. Ayah highlight & center scroll only when Ayah transitions
        if (aNum !== lastActiveAyahNum) {
          const ayahEl = ayahCache[aNum];
          if (ayahEl && ayahEl !== currentActiveAyahEl) {
            if (currentActiveAyahEl) currentActiveAyahEl.classList.remove("active-ayah");
            ayahEl.classList.add("active-ayah");
            currentActiveAyahEl = ayahEl;

            if (aNum !== lastScrolledAyah) {
              lastScrolledAyah = aNum;
              ayahEl.scrollIntoView({ behavior: "smooth", block: "center" });
            }
          }
          lastActiveAyahNum = aNum;
        }

        // 2. Highlighting Modes Dispatcher (letter | word | ayah | off)
        if (activeHighlightMode === "off" || activeHighlightMode === "ayah") {
          if (currentRecitingWordEl) {
            currentRecitingWordEl.classList.remove("reciting", "word-active");
            currentRecitingWordEl = null;
          }
          if (currentActiveCharEl) {
            currentActiveCharEl.classList.remove("active-char");
            currentActiveCharEl = null;
          }
          lastActiveWordIdx = -1;
        } else if (activeHighlightMode === "letter") {
          // Letter-Level Continuous Flow & Glow
          const vKey = currentVerseKey || (surahNumber + ":" + aNum);
          const letters = letterTimingMap[vKey] || letterTimingMap[String(aNum)] || [];
          let activeLetter = null;
          if (letters && letters.length > 0) {
            for (let i = 0; i < letters.length; i++) {
              const lt = letters[i];
              if (timeMs >= lt.start && timeMs < lt.end) {
                activeLetter = lt;
                break;
              }
            }
          }
          if (activeLetter) {
            const wIdx = activeLetter.wordIdx;
            const cIdx = activeLetter.charIdx;

            // Activate word background glow
            const wEl = wordCache[aNum] ? wordCache[aNum][wIdx] : null;
            if (wEl && wEl !== currentRecitingWordEl) {
              if (currentRecitingWordEl) currentRecitingWordEl.classList.remove("reciting", "word-active");
              wEl.classList.add("word-active");
              currentRecitingWordEl = wEl;
            }

            // Activate character glow
            const cEl = charCache[aNum] && charCache[aNum][wIdx] ? charCache[aNum][wIdx][cIdx] : null;
            if (cEl && cEl !== currentActiveCharEl) {
              if (currentActiveCharEl) currentActiveCharEl.classList.remove("active-char");
              cEl.classList.add("active-char");
              currentActiveCharEl = cEl;
            }
          } else {
            // Fall back to word mode if no letter entry for this frame
            syncWordHighlight(aNum, timeMs);
          }
        } else {
          // Word-Level Highlighting (Default)
          if (currentActiveCharEl) {
            currentActiveCharEl.classList.remove("active-char");
            currentActiveCharEl = null;
          }
          syncWordHighlight(aNum, timeMs);
        }
      }
      requestAnimationFrame(renderFrame);
    }
    requestAnimationFrame(renderFrame);

    // Interactive Tap Handling with Gesture Disambiguation
    let pendingTapTimer = null;
    let lastTapTime = 0;
    let lastTapTarget = null;

    document.addEventListener("click", function(e) {
      const wordEl = e.target.closest(".word");
      const ayahMedallionEl = e.target.closest(".ayah-medallion");
      const now = Date.now();

      // 1. Explicit Ayah Medallion Tap -> Immediate Full Verse Playback
      if (ayahMedallionEl) {
        if (pendingTapTimer) {
          clearTimeout(pendingTapTimer);
          pendingTapTimer = null;
        }
        const ayah = parseInt(ayahMedallionEl.getAttribute("data-ayah"), 10);
        if (window.ReactNativeWebView) {
          window.ReactNativeWebView.postMessage(JSON.stringify({
            type: "SEEK_AYAH",
            ayah: ayah
          }));
        }
        return;
      }

      // 2. Word Tap Disambiguation (1-Tap: Isolated Word Audio, 2-Taps: Letters HUD)
      if (wordEl) {
        const ayah = parseInt(wordEl.getAttribute("data-ayah"), 10);
        const wordIdx = parseInt(wordEl.getAttribute("data-word-idx"), 10);
        const wordText = decodeURIComponent(wordEl.getAttribute("data-word-text") || "");

        // If a second tap occurs on the same word within 280ms:
        if (lastTapTarget === wordEl && (now - lastTapTime) < 280) {
          // CANCEL the pending single tap action!
          if (pendingTapTimer) {
            clearTimeout(pendingTapTimer);
            pendingTapTimer = null;
          }
          lastTapTime = 0;
          lastTapTarget = null;

          // Emit DOUBLE CLICK (Letters Breakdown & Phonetics HUD)
          if (window.ReactNativeWebView) {
            window.ReactNativeWebView.postMessage(JSON.stringify({
              type: "WORD_DOUBLE_CLICK",
              surah: surahNumber,
              ayah: ayah,
              wordIdx: wordIdx,
              wordText: wordText
            }));
          }
          return;
        }

        // First tap: record state and start debounce timer
        lastTapTime = now;
        lastTapTarget = wordEl;

        if (pendingTapTimer) {
          clearTimeout(pendingTapTimer);
        }

        pendingTapTimer = setTimeout(function() {
          pendingTapTimer = null;
          lastTapTarget = null;

          // Single Tap Action: Play isolated word audio
          if (window.ReactNativeWebView) {
            window.ReactNativeWebView.postMessage(JSON.stringify({
              type: "WORD_SINGLE_CLICK",
              surah: surahNumber,
              ayah: ayah,
              wordIdx: wordIdx,
              wordText: wordText
            }));
          }
        }, 280);

        return;
      }
    });
  </script>
</body>
</html>`;
  }, [surahNumber, verses?.length]);

  const webViewSource = useMemo(() => ({ html: htmlContent }), [htmlContent]);

  const lastPlaybackUpdateRef = useRef({ timeMs: -1, verseKey: "", isPlaying: false });

  // Send real-time playback updates to the WebView without reloading
  useEffect(() => {
    if (!webViewRef.current) return;

    const last = lastPlaybackUpdateRef.current;
    const timeDelta = Math.abs((currentTimeMs || 0) - last.timeMs);
    const keyChanged = currentVerseKey !== last.verseKey;
    const playChanged = isPlaying !== last.isPlaying;

    // Throttle sub-25ms updates to preserve 120 FPS frame budget
    if (!keyChanged && !playChanged && timeDelta < 25) {
      return;
    }

    lastPlaybackUpdateRef.current = {
      timeMs: currentTimeMs || 0,
      verseKey: currentVerseKey || "",
      isPlaying,
    };

    const msg = JSON.stringify({
      type: "UPDATE_PLAYBACK",
      currentTimeMs: currentTimeMs || 0,
      currentVerseKey: currentVerseKey || "",
      isPlaying,
      highlightMode,
    });
    try {
      webViewRef.current.postMessage(msg);
    } catch (postErr) {
      console.warn("WebView postMessage transmission failed:", postErr);
    }
  }, [currentTimeMs, currentVerseKey, isPlaying, highlightMode]);

  const handleMessage = (event: any) => {
    try {
      const bridgePayload = JSON.parse(event.nativeEvent.data);
      if (bridgePayload.type === "SEEK_AYAH" && onSeekAyah) {
        onSeekAyah(bridgePayload.ayah);
      } else if (bridgePayload.type === "WORD_SINGLE_CLICK") {
        if (onWordSingleClick) {
          onWordSingleClick(bridgePayload.surah, bridgePayload.ayah, bridgePayload.wordIdx, bridgePayload.wordText);
        } else if (onWordClick) {
          onWordClick(bridgePayload.surah, bridgePayload.ayah, bridgePayload.wordIdx, bridgePayload.wordText);
        }
      } else if (bridgePayload.type === "WORD_DOUBLE_CLICK") {
        if (onWordDoubleClick) {
          onWordDoubleClick(bridgePayload.surah, bridgePayload.ayah, bridgePayload.wordIdx, bridgePayload.wordText);
        } else if (onWordClick) {
          onWordClick(bridgePayload.surah, bridgePayload.ayah, bridgePayload.wordIdx, bridgePayload.wordText);
        }
      }
    } catch (parseErr) {
      console.warn("Failed to parse WebView bridge payload:", parseErr);
    }
  };

  return (
    <View style={styles.container}>
      <WebView
        ref={webViewRef}
        originWhitelist={["*"]}
        source={webViewSource}
        style={styles.webview}
        androidLayerType="hardware"
        javaScriptEnabled={true}
        domStorageEnabled={true}
        onMessage={handleMessage}
        scrollEnabled={true}
        overScrollMode="never"
        showsVerticalScrollIndicator={false}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    width: "100%",
    height: "100%",
    backgroundColor: "#030712",
  },
  webview: {
    flex: 1,
    width: "100%",
    height: "100%",
    backgroundColor: "#030712",
  },
});
